'use strict';
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),{createRequire}=require('node:module');
const file=path.resolve('miniapp/tests/schedule-service.test.cjs'),req=createRequire(file),m={exports:{}};
vm.runInNewContext(fs.readFileSync(file,'utf8')+'\nmodule.exports={createConflictMockDb,seedConflictProject,createConflictService,createMockDb,seedProject,memberId,compatForm,makeBarrier};',{module:m,exports:m.exports,require:n=>n==='node:test'?()=>{}:req(n),Date,console,Buffer});
const h=m.exports,sched=req('../cloudfunctions/memberAccess/schedule-service'),member=req('../cloudfunctions/memberAccess/service');
const results=[];
async function attempt(fn){try{return{result:await fn()};}catch(e){return{code:e.code,message:e.message};}}
async function record(name,fn){try{results.push({name,...await fn()});}catch(e){results.push({name,replayError:e.message,code:e.code});}}
function setup(){const db=h.createConflictMockDb(),ids=h.seedConflictProject(db,'p1','manager_openid','worker_openid','worker2_openid','水电');return{db,ids,call:h.createConflictService(db).call};}
function togetherAfterReceipt(db){const original=db.runTransaction;let started=0,finished=0,release;const gate=new Promise(r=>release=r);db.runTransaction=async work=>{const n=++started;const result=await original(work);if(n<=2){finished++;if(finished===2)release();await gate;}return result;};}
(async()=>{
for(const action of ['createSchedule','updateSchedule','reassignSchedule','cancelSchedule'])await record('concurrent_same_id_'+action,async()=>{const{db,ids}=setup();const call1=h.createConflictService(db).call,call2=h.createConflictService(db).call;const form=h.compatForm(ids.workerUserId,'2026-10-01','2026-10-02');let body={projectId:'p1',requestId:'shared',form};if(action!=='createSchedule'){const s=await call1('manager_openid','createSchedule',{projectId:'p1',requestId:'seed',form});body={...body,scheduleId:s.scheduleId,expectedVersion:1,reason:'review',workerUserId:ids.worker2UserId,form:{...form,content:'changed'}};}togetherAfterReceipt(db);const outcomes=await Promise.all([attempt(()=>call1('manager_openid',action,body)),attempt(()=>call2('manager_openid',action,body))]);const d=db.getData();return{outcomes,expected:'both same original success, only one mutation',scheduleCount:Object.keys(d.schedules).length,receiptCount:Object.keys(d.schedule_receipts).length,auditCount:Object.keys(d.audit_events).length};});
await record('two_distinct_first_use_creates',async()=>{const{db,ids}=setup();const a=h.createConflictService(db).call,b=h.createConflictService(db).call;togetherAfterReceipt(db);const outcomes=await Promise.all([attempt(()=>a('manager_openid','createSchedule',{projectId:'p1',requestId:'a',form:h.compatForm(ids.workerUserId,'2026-10-01','2026-10-01')})),attempt(()=>b('manager_openid','createSchedule',{projectId:'p1',requestId:'b',form:h.compatForm(ids.workerUserId,'2026-10-02','2026-10-02')}))]);const d=db.getData();return{outcomes,scheduleCount:Object.keys(d.schedules).length,guard:d.member_task_guard['p1:'+ids.workerUserId]};});
await record('counter_attempt_isolation',async()=>{const db=h.createMockDb();h.seedProject(db,'p1','u_manager','u_worker','水电');const s=sched.createScheduleService(db),barrier=h.makeBarrier();let aReads=0,bReads=0;const a=attempt(()=>s.runWithScanRounds({collect:async()=>null,run:async tx=>{for(let i=0;i<90;i++){if(i===60){barrier.signal();await barrier.wait;}await tx.collection('users').doc('u_worker').get();aReads++;}return'completed';}}));await barrier.reached;const b=await attempt(()=>s.runWithScanRounds({collect:async()=>null,run:async tx=>{for(let i=0;i<10;i++){await tx.collection('users').doc('u_worker').get();bReads++;}return'completed';}}));barrier.resume();return{a:await a,b,aReads,bReads,expected:'A must stop before underlying operation 81'};});
await record('maintenance_switch_after_permission_revoked',async()=>{const{db,ids,call}=setup();const original=db.runTransaction;db.runTransaction=async work=>{db.mutate(d=>{d.project_members[h.memberId('p1',ids.managerUserId)].status='left';d.users[ids.managerUserId].status='disabled';});return original(work);};const outcome=await attempt(()=>call('manager_openid','setScheduleWriteMode',{projectId:'p1',mode:'maintenance'}));return{...outcome,mode:db.getData().projects.p1.scheduleWriteMode,managerStatus:db.getData().project_members[h.memberId('p1',ids.managerUserId)].status};});
await record('ready_switch_without_repair_validation',async()=>{const{db,ids,call}=setup();db.mutate(d=>{d.projects.p1.scheduleWriteMode='maintenance';delete d.project_members[h.memberId('p1',ids.workerUserId)].taskDirSchemaVersion;});return{...await attempt(()=>call('manager_openid','setScheduleWriteMode',{projectId:'p1',mode:'ready'})),mode:db.getData().projects.p1.scheduleWriteMode};});
const report={recordedAt:new Date().toISOString(),scope:'offline synthetic only; no cloud',results};const out=path.join(process.env.TEMP||require('node:os').tmpdir(),'yf-t1-t7-additional.json');fs.writeFileSync(out,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));
})().catch(e=>{console.error(e);process.exitCode=1;});
